BEGIN;
-- Additive after 005: no real or synthetic world is generated by migration.
CREATE TABLE world_entities (
  id uuid PRIMARY KEY,sequence bigserial NOT NULL UNIQUE,game_id uuid NOT NULL REFERENCES games(id),
  entity_key text NOT NULL,category text NOT NULL CHECK(category IN ('world','place','faction','npc')),
  kind text NOT NULL,name text NOT NULL,description text NOT NULL,status text NOT NULL,state jsonb NOT NULL,
  parent_id uuid,location_id uuid,affiliation_id uuid,active boolean NOT NULL,
  visibility text NOT NULL CHECK(visibility IN ('player','gm')),gm_notes text NOT NULL,gm_state jsonb NOT NULL,
  version integer NOT NULL DEFAULT 1 CHECK(version>0),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK((category='world' AND parent_id IS NULL AND location_id IS NULL AND affiliation_id IS NULL) OR (category<>'world' AND parent_id IS NOT NULL)),
  CHECK(id IS DISTINCT FROM parent_id AND id IS DISTINCT FROM location_id AND id IS DISTINCT FROM affiliation_id),
  UNIQUE(game_id,id),UNIQUE(game_id,entity_key),
  FOREIGN KEY(game_id,parent_id) REFERENCES world_entities(game_id,id),
  FOREIGN KEY(game_id,location_id) REFERENCES world_entities(game_id,id),
  FOREIGN KEY(game_id,affiliation_id) REFERENCES world_entities(game_id,id)
);
CREATE UNIQUE INDEX world_single_root ON world_entities(game_id) WHERE category='world';
CREATE TABLE world_relations (
  id uuid PRIMARY KEY,sequence bigserial NOT NULL UNIQUE,game_id uuid NOT NULL REFERENCES characters(game_id),relation_key text NOT NULL,
  from_entity_id uuid,to_entity_id uuid,from_character boolean NOT NULL,to_character boolean NOT NULL,
  kind text NOT NULL,description text NOT NULL,state jsonb NOT NULL,active boolean NOT NULL,
  visibility text NOT NULL CHECK(visibility IN ('player','gm')),gm_notes text NOT NULL,gm_state jsonb NOT NULL,
  version integer NOT NULL DEFAULT 1 CHECK(version>0),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CHECK(from_character=(from_entity_id IS NULL) AND to_character=(to_entity_id IS NULL)),
  CHECK(from_entity_id IS DISTINCT FROM to_entity_id),UNIQUE(game_id,id),UNIQUE(game_id,relation_key),
  FOREIGN KEY(game_id,from_entity_id) REFERENCES world_entities(game_id,id),FOREIGN KEY(game_id,to_entity_id) REFERENCES world_entities(game_id,id)
);
CREATE TABLE world_facts (
  id uuid PRIMARY KEY,sequence bigserial NOT NULL UNIQUE,game_id uuid NOT NULL REFERENCES games(id),fact_key text NOT NULL,
  kind text NOT NULL CHECK(kind IN ('event','history','setting','foreshadowing')),title text NOT NULL,body text NOT NULL,
  truth text NOT NULL CHECK(truth IN ('canon','claim','belief')),speaker_id uuid,world_time jsonb,
  visibility text NOT NULL CHECK(visibility IN ('player','gm')),gm_notes text NOT NULL,gm_state jsonb NOT NULL,
  version integer NOT NULL DEFAULT 1 CHECK(version>0),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),revealed_at timestamptz,
  CHECK((truth='canon' AND speaker_id IS NULL) OR (truth IN ('claim','belief') AND speaker_id IS NOT NULL)),
  UNIQUE(game_id,id),UNIQUE(game_id,fact_key),FOREIGN KEY(game_id,speaker_id) REFERENCES world_entities(game_id,id)
);
CREATE TABLE gm_memories (
  id uuid PRIMARY KEY,sequence bigserial NOT NULL UNIQUE,game_id uuid NOT NULL REFERENCES games(id),memory_key text NOT NULL,
  kind text NOT NULL,title text NOT NULL,body text NOT NULL,active boolean NOT NULL,
  visibility text NOT NULL CHECK(visibility IN ('player','gm')),gm_notes text NOT NULL,gm_state jsonb NOT NULL,
  version integer NOT NULL DEFAULT 1 CHECK(version>0),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(game_id,id),UNIQUE(game_id,memory_key)
);
CREATE TABLE adventure_journals (
  id uuid PRIMARY KEY,sequence bigserial NOT NULL UNIQUE,game_id uuid NOT NULL REFERENCES games(id),journal_key text NOT NULL,
  title text NOT NULL,body text NOT NULL,world_time jsonb,
  visibility text NOT NULL CHECK(visibility IN ('player','gm')),gm_notes text NOT NULL,gm_state jsonb NOT NULL,
  version integer NOT NULL DEFAULT 1 CHECK(version>0),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(game_id,id),UNIQUE(game_id,journal_key)
);
-- Three concrete record link tables. Source FK/history is retained in change snapshots.
CREATE TABLE world_fact_links (
  game_id uuid NOT NULL,record_id uuid NOT NULL,ordinal integer NOT NULL,
  entity_id uuid,fact_id uuid,questline_id uuid,event_id uuid,event_version integer,
  PRIMARY KEY(record_id,ordinal),CHECK(num_nonnulls(entity_id,fact_id,questline_id,event_id)=1),CHECK((event_id IS NULL)=(event_version IS NULL)),
  FOREIGN KEY(game_id,record_id) REFERENCES world_facts(game_id,id),
  FOREIGN KEY(game_id,entity_id) REFERENCES world_entities(game_id,id),FOREIGN KEY(game_id,fact_id) REFERENCES world_facts(game_id,id),
  FOREIGN KEY(game_id,questline_id) REFERENCES questlines(game_id,id),FOREIGN KEY(event_id,event_version) REFERENCES life_event_revisions(event_id,version)
);
CREATE TABLE gm_memory_links (LIKE world_fact_links INCLUDING CONSTRAINTS INCLUDING INDEXES);
ALTER TABLE gm_memory_links ADD FOREIGN KEY(game_id,record_id) REFERENCES gm_memories(game_id,id),
  ADD FOREIGN KEY(game_id,entity_id) REFERENCES world_entities(game_id,id),ADD FOREIGN KEY(game_id,fact_id) REFERENCES world_facts(game_id,id),
  ADD FOREIGN KEY(game_id,questline_id) REFERENCES questlines(game_id,id),ADD FOREIGN KEY(event_id,event_version) REFERENCES life_event_revisions(event_id,version);
CREATE TABLE adventure_journal_links (LIKE world_fact_links INCLUDING CONSTRAINTS INCLUDING INDEXES);
ALTER TABLE adventure_journal_links ADD FOREIGN KEY(game_id,record_id) REFERENCES adventure_journals(game_id,id),
  ADD FOREIGN KEY(game_id,entity_id) REFERENCES world_entities(game_id,id),ADD FOREIGN KEY(game_id,fact_id) REFERENCES world_facts(game_id,id),
  ADD FOREIGN KEY(game_id,questline_id) REFERENCES questlines(game_id,id),ADD FOREIGN KEY(event_id,event_version) REFERENCES life_event_revisions(event_id,version);
CREATE TABLE world_clocks (
  game_id uuid PRIMARY KEY,root_id uuid NOT NULL,world_time jsonb,last_world_advanced_at timestamptz NOT NULL,
  FOREIGN KEY(game_id,root_id) REFERENCES world_entities(game_id,id)
);
CREATE TABLE world_change_entries (
  sequence bigserial PRIMARY KEY,game_id uuid NOT NULL,update_id uuid NOT NULL,ordinal integer NOT NULL,
  target_type text NOT NULL CHECK(target_type IN ('entity','relation','fact','memory','journal','clock')),
  target_id uuid NOT NULL,reason text NOT NULL,before_state jsonb,after_state jsonb NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(update_id,ordinal),
  FOREIGN KEY(game_id,update_id) REFERENCES gm_updates(game_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX world_history_target ON world_change_entries(game_id,target_id,sequence);
CREATE INDEX world_entities_game_page ON world_entities(game_id,sequence);
CREATE INDEX world_relations_game_page ON world_relations(game_id,sequence);
CREATE INDEX world_facts_game_page ON world_facts(game_id,sequence);
CREATE INDEX gm_memories_game_page ON gm_memories(game_id,sequence);
CREATE INDEX adventure_journals_game_page ON adventure_journals(game_id,sequence);
CREATE TRIGGER world_history_immutable BEFORE UPDATE OR DELETE ON world_change_entries FOR EACH ROW EXECUTE FUNCTION protect_life_event_history();
COMMIT;
